import{_ as t,o,c as a,a2 as s}from"./chunks/framework.Wk4ah3nE.js";const m=JSON.parse('{"title":"Introduction","description":"What Proxmox VM Autoscale does, what it deliberately does not do, and the assumptions it makes about your Proxmox environment.","frontmatter":{"title":"Introduction","description":"What Proxmox VM Autoscale does, what it deliberately does not do, and the assumptions it makes about your Proxmox environment.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/"}],["meta",{"property":"og:title","content":"Introduction"}],["meta",{"property":"og:description","content":"What Proxmox VM Autoscale does, what it deliberately does not do, and the assumptions it makes about your Proxmox environment."}]]},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":null}'),i={name:"guide/index.md"};function n(r,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Proxmox VM Autoscale is a long-running Python service that adjusts the CPU cores and RAM of Proxmox VE virtual machines based on how much of each they are actually using.</p><p>It runs as a systemd unit, connects to one or more Proxmox nodes over SSH, and drives the standard <code>qm</code> and <code>pvesh</code> command-line tools. There is no agent inside the guests and no Proxmox API token: everything happens through an SSH session as a user who can run <code>qm</code>.</p><h2 id="the-loop-in-one-paragraph" tabindex="-1">The loop, in one paragraph <a class="header-anchor" href="#the-loop-in-one-paragraph" aria-label="Permalink to &quot;The loop, in one paragraph&quot;">​</a></h2><p>Every <code>check_interval</code> seconds the service walks the VMs listed in <code>config.yaml</code>. For each one it confirms the guest is running, checks that the <strong>host</strong> still has headroom, reads the guest&#39;s current CPU and RAM usage, and compares those numbers against your thresholds. If usage is above the high mark it adds one core or 512 MB; if it is below the low mark it removes one. Limits and a per-resource cooldown bound how far and how fast that can go. Any actual change is logged and, if you configured it, pushed to Gotify or emailed.</p><p>That is the whole design. The rest of the documentation is about the details that decide whether it behaves well on your hardware.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ul><li><strong>Vertical scaling of CPU cores and vCPUs</strong> on a running or stopped guest.</li><li><strong>Vertical scaling of RAM</strong>, via the balloon device when hotplug and NUMA allow it, otherwise as a config change that needs a reboot.</li><li><strong>Multi-host operation</strong> — several Proxmox nodes in one config file, each with its own SSH credentials and port.</li><li><strong>Host-level safety gating</strong> so a busy node does not get pushed further.</li><li><strong>Hotplug and NUMA auto-configuration</strong>, optional, so guests become live-scalable without you touching each one by hand.</li><li><strong>Gotify and SMTP notifications</strong> on scaling actions and errors.</li><li><strong>Spec-change recording</strong> for usage-based billing, with a costed CSV report.</li></ul><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><p>Being explicit about this saves a lot of disappointment:</p><ul><li><strong>No horizontal scaling.</strong> It never creates, clones, destroys or migrates a VM. It only resizes the ones you list.</li><li><strong>No LXC containers.</strong> Use the sibling project <a href="https://github.com/fabriziosalmi/proxmox-lxc-autoscale" target="_blank" rel="noreferrer">proxmox-lxc-autoscale</a> for those.</li><li><strong>No disk, network or GPU scaling.</strong> CPU cores, vCPUs and memory only.</li><li><strong>No prediction or trend analysis.</strong> Decisions come from a single instantaneous sample per cycle. There is no smoothing, no moving average and no seasonality — a one-off spike between two polls is invisible, and a spike caught by a poll is acted on immediately.</li><li><strong>No dry-run mode.</strong> If the service is running and a threshold is crossed, <code>qm set</code> is executed.</li><li><strong>No per-VM thresholds.</strong> <code>config.yaml</code> shows a <code>thresholds:</code> block inside each VM entry, but the code reads only the global <code>scaling_thresholds</code>. See <a href="/proxmox-vm-autoscale/reference/limitations.html#per-vm-thresholds-are-ignored">known limitations</a>.</li><li><strong>No high availability.</strong> It is a single process. If it dies, systemd restarts it and the in-memory cooldown state starts over.</li></ul><h2 id="assumptions-it-makes" tabindex="-1">Assumptions it makes <a class="header-anchor" href="#assumptions-it-makes" aria-label="Permalink to &quot;Assumptions it makes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Assumption</th><th>Why it matters</th></tr></thead><tbody><tr><td>You can SSH to each Proxmox node as a user who may run <code>qm set</code> — in practice <code>root</code></td><td>Every action is a shell command; there is no least-privilege mode today</td></tr><tr><td>Guests are QEMU/KVM VMs, not containers</td><td>Usage is read from <code>qemu/&lt;vmid&gt;</code> rows in <code>pvesh get /cluster/resources</code></td></tr><tr><td><code>pvesh</code> output format is stable on your Proxmox version</td><td>Usage parsing is text-based and version-sensitive — see <a href="/proxmox-vm-autoscale/reference/limitations.html#metric-parsing-is-format-sensitive">limitations</a></td></tr><tr><td>Guests you want live-scaled have hotplug <strong>and</strong> NUMA on</td><td>Without both, memory changes need a reboot to apply</td></tr><tr><td>Load is bursty and uncorrelated across VMs</td><td>If everything peaks together, the host ceiling blocks scaling and you simply need more hardware</td></tr></tbody></table><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>Proxmox VE 6.0 or newer</strong> on the target nodes.</li><li><strong>Python 3.9 or newer</strong> on the machine running the service. (CI tests 3.9 through 3.12. The README&#39;s older &quot;3.6+&quot; claim is not backed by any test run.)</li><li><strong><code>paramiko</code>, <code>PyYAML</code>, <code>requests</code></strong> — see <code>requirements.txt</code>.</li><li><strong>SSH reachability</strong> from the service to every node in the config.</li></ul><div class="tip custom-block"><p class="custom-block-title">Where to run it</p><p>The service can run <em>on</em> a Proxmox node (simplest, and what the installer assumes) or on a separate Linux box that has SSH access to all of them. Running it off-node means a node reboot does not take the autoscaler down with it — but it also means the autoscaler&#39;s credentials live somewhere else that must be protected just as well.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/proxmox-vm-autoscale/guide/installation.html">Install it</a> — installer, or manual setup if you would rather not pipe a script into bash.</li><li><a href="/proxmox-vm-autoscale/guide/quick-start.html">Get one VM scaling</a> — the smallest useful configuration, and how to prove it works.</li><li><a href="/proxmox-vm-autoscale/guide/how-it-works.html">Understand the decision logic</a> — thresholds, step sizes, limits, cooldowns.</li></ul>',18)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
